def find_tile(g):
    H,W=len(g),len(g[0])
    # horizontal: full column of one non-bg color as divider
    for c in range(W):
        col={g[r][c] for r in range(H)}
        if len(col)==1 and next(iter(col))!=0:
            # candidate divider; check preceding content non-bg somewhere before first divider
            p=c+1
            if p<=W:
                tile=[row[:p] for row in g]
                if any(x!=tile[0][0] or True for r in tile for x in [0]):
                    # require some non-bg cell in tile (bg = most common)
                    from collections import Counter
                    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
                    if any(x!=bg for row in tile for x in row):
                        return ('h',p,tile)
    # vertical: full row of one color (incl 0) as divider
    from collections import Counter
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    for r in range(H):
        row=set(g[r])
        if len(row)==1:
            p=r+1
            if p<=H:
                tile=g[:p]
                if any(x!=bg for rr in tile for x in rr):
                    return ('v',p,tile)
    return None

def transform(g):
    r=find_tile(g)
    d,p,tile=r
    H,W=len(g),len(g[0])
    out=[]
    if d=='v':
        for i in range(H):
            out.append(list(tile[i%p]))
    else:
        out=[[tile[i][j%p] for j in range(W)] for i in range(H)]
    return out

